"""Explain bitmap initialization, fields and zero-area search."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1369': ('64칸짜리 내용을 32칸 상자에 담으려면 상자 둘이 필요합니다. 앞 상자에는 낮은 번호, 뒤 상자에는 높은 번호의 내용을 넣습니다.', '큰 정수를 비트맵 배열의 처음 값으로 나누어 넣는 방법을 배웁니다.', '번호 42를 32로 나누세요. 몫 1, 나머지 10입니다. 배열 번호 1은 두 번째 상자이고 그 안의 10번 칸이라고 적으세요.', ['BITMAP_FROM_U64는 배열을 만들 때 처음 넣을 값들을 펼쳐 주는 매크로입니다. 매크로는 C 코드를 만들기 전에 글처럼 펼쳐지는 규칙입니다. u64는 64비트 부호 없는 정수이고 비트맵의 상자 하나는 unsigned long입니다.', 'unsigned long이 64비트인 환경에서는 입력 n 하나가 그대로 한 원소가 됩니다. 32비트인 환경에서는 낮은 32비트와 높은 32비트 두 원소로 나뉩니다. 배열 초기값의 중괄호 안에서 사용할 때 환경에 맞는 원소 수가 만들어집니다.', '낮은 부분은 u64로 해석한 n과 ULONG_MAX를 AND해서 고릅니다. 이 32비트 환경의 ULONG_MAX는 낮은 32칸이 모두 1인 마스크입니다. 높은 부분은 먼저 u64로 해석하고 오른쪽으로 32칸 옮겨 얻습니다.', '예를 들어 0x0000000200000001은 앞 원소 1, 뒤 원소 2로 나뉩니다. 0x는 16진수 표시입니다. 비트 42는 42=32×1+10이므로 배열 번호 1, 즉 두 번째 원소의 10번 비트입니다. 첫 원소 안에 42번 칸이 있는 것이 아닙니다.', 'big endian은 큰 자리의 바이트를 메모리 앞쪽에 두는 저장 순서입니다. 32비트 big endian에서 u64 메모리를 그대로 두 word로 읽으면 높은 부분이 먼저 나올 수 있습니다. 이 매크로는 숫자를 나누어 낮은 부분부터 명시하므로 비트맵의 순서를 맞춥니다.', '32비트 경로에는 n이 두 식에 나타납니다. 값을 임시 변수에 한 번만 보관하는 매크로가 아닙니다. 호출할 때마다 값이 바뀌는 함수나 x++ 같은 입력을 쓰지 말고, 미리 정한 같은 값을 넣으세요. 입력의 계산 횟수까지 확인해야 두 부분이 같은 원본에서 나옵니다.'], [('32비트 word 배열에서 전체 비트 번호 42는 어디에 있을까요?', ['첫 번째 word의 42번 칸이에요', '두 번째 word의 10번 칸이에요'], '첫 word는 전체 0~31번을 맡습니다. 42에서 32를 빼면 10이므로 다음 word의 10번입니다. 배열 번호는 0부터여서 두 번째 원소의 번호는 1입니다.'), ('32비트 매크로는 입력 n을 두 초기값 식에 넣을까요?', ['네. 낮은 부분과 높은 부분 식에 각각 넣어요', '아니요. 언제나 한 번 계산한 임시 값을 재사용해요'], '원문에 n이 두 번 나타나고 임시 변수는 없습니다. 따라서 값을 바꾸는 표현을 넣어도 한 번만 계산될 것이라고 가정하면 안 됩니다.')]), 'os1370': ('한 줄에 64칸인 공책에서 60번부터 여덟 칸을 읽어 봅시다. 첫 줄에 네 칸만 남았으므로 다음 줄에서도 네 칸을 읽어 이어야 합니다.', 'word의 끝을 가로지르는 비트 묶음을 읽는 과정을 배웁니다.', '64비트 word의 60~63번을 먼저 표시하고 다음 word의 0~3번을 표시하세요. 두 조각을 합쳐 여덟 비트를 읽는다고 적으세요.', ['bitmap_read는 start부터 nbits개 비트를 꺼내 하나의 unsigned long 값으로 돌려줍니다. map은 읽을 비트맵입니다. 원본 비트맵을 바꾸지는 않습니다. 읽을 묶음의 폭 nbits는 문서상 1부터 word 폭까지입니다.', '먼저 start를 word 폭으로 나누어 어느 word인지 구합니다. 나머지는 그 word 안의 시작 번호 offset입니다. space는 그 위치부터 word 끝까지 남은 칸 수입니다. 64비트에서 start=60이면 offset=60, space=4입니다.', 'space가 nbits 이상이면 한 word만 읽습니다. 시작 위치가 낮은 0번으로 오도록 오른쪽으로 옮기고, 원하는 칸만 1인 마스크를 AND해 나머지를 지웁니다. 이 결과의 0번 비트가 원래 start의 값입니다.', 'start=60, nbits=8이면 space=4라 부족합니다. 현재 word의 끝 네 칸과 다음 word의 처음 네 칸을 따로 고릅니다. 앞 조각을 결과의 낮은 네 칸으로 옮기고 뒤 조각을 네 칸 왼쪽으로 옮겨 합칩니다.', '현재 끝 조각이 1010, 다음 처음 조각이 0011이면 결과는 00111010입니다. 앞 조각이 낮은 자리이고 다음 조각이 높은 자리입니다. 숫자 그림은 높은 번호를 왼쪽에 쓰므로 읽는 순서와 그림의 좌우를 구별하세요.', '이 v6.12 구현은 nbits가 0이거나 word 폭보다 크면 배열을 읽기 전에 0을 반환합니다. 하지만 문서는 그 폭의 결과를 사용 약속으로 보장하지 않습니다. 정상 사용은 유효 폭을 지켜야 하며, 경계를 넘으면 다음 word까지 실제 공간이 있는지도 호출자가 보장해야 합니다.'], [('64비트 word에서 60번부터 8비트를 읽으면 몇 word에 걸칠까요?', ['항상 한 word 안에 있어요', '두 word에 걸쳐 있어요'], '첫 word에 남은 것은 60,61,62,63번 네 칸입니다. 나머지 네 칸을 다음 word에서 읽어야 총 여덟 칸이 됩니다.'), ('지금 보는 v6.12 구현에 폭 65를 넣으면 초기 분기는 무엇을 할까요?', ['배열을 읽기 전에 0을 반환해요', '아무 다음 word나 반드시 읽어요'], '이 커널의 word 폭은 32 또는 64비트이므로 65는 둘 다 넘습니다. 초기 조건이 0을 반환합니다. 다만 문서가 보장하는 정상 폭은 아니므로 이 관찰을 잘못된 폭을 써도 된다는 약속으로 바꾸면 안 됩니다.')]), 'os1371': ('긴 칸 줄의 여덟 칸만 새 숫자로 고쳐 봅시다. 그 칸의 옛 숫자는 지워야 하지만 양옆에 쓰인 숫자는 그대로 남겨야 합니다.', '비트를 쓸 때 값의 잘라내기와 바깥 칸 보존을 이해합니다.', '기존 여덟 칸이 11111111이고 2번부터 세 칸에 값 1001을 쓴다고 적으세요. 낮은 세 비트 001만 사용하여 결과가 11100111이 되는지 칸별로 확인하세요.', ['bitmap_write는 value의 낮은 nbits개 비트를 map의 start부터 씁니다. 비트 번호는 0부터입니다. 문서가 말하는 정상 폭은 1부터 word 폭까지이며, 출력 공간이 실제로 충분해야 합니다.', '먼저 nbits가 0이거나 word 폭보다 큰지 확인합니다. 그렇다면 아무것도 쓰지 않고 돌아갑니다. 폭 0이 word 전체를 지우라는 뜻은 아닙니다.', '정상 폭이면 value &= mask로 높은 비트를 버립니다. 세 칸에 1001을 쓰면 낮은 세 칸 001만 남습니다. 숫자가 크다고 오류를 반환하거나 최대값 111로 바꾸는 동작이 아닙니다. 큰 값을 거절하려면 호출 전에 따로 확인해야 합니다.', '한 word 안에 들어가면 쓸 자리의 옛 비트만 먼저 지우고 새 값을 OR로 넣습니다. 옛 1 위에 새 0을 써야 할 수 있으므로 먼저 지우는 단계가 필요합니다. OR만 하면 옛 1을 0으로 바꿀 수 없습니다.', '두 word에 걸치면 첫 word의 끝 부분을 고치고 다음 word의 처음 부분을 고칩니다. 앞뒤의 바깥 비트는 마스크로 남깁니다. 64비트 환경에서 start=60, nbits=8이면 첫 word 네 칸과 다음 word 네 칸에 나누어 씁니다.', '다른 실행 흐름의 변경이 없다면 지정 범위 밖의 비트는 보존됩니다. 그러나 여러 읽기와 쓰기가 나뉘어 있으므로 동시에 고치는 작업 전체를 자동으로 보호하지는 않습니다. 함께 사용하는 코드에는 잠금 같은 보호 규칙이 필요합니다.'], [('세 비트만 쓸 때 value의 그보다 높은 비트는 어떻게 될까요?', ['항상 오류를 반환해요', '마스크로 버리고 낮은 세 비트만 써요'], '1001은 낮은 세 비트 001이 됩니다. 함수는 값을 마스크로 제한하며 반환형 void라 오류 값을 돌려주지도 않습니다. 높은 비트를 버리는 것과 큰 숫자를 거절하는 것은 다릅니다.'), ('폭 nbits가 0이면 비트맵이 바뀔까요?', ['아니요. 처음 조건에서 쓰지 않고 돌아가요', '네. 첫 word 전체를 0으로 만들어요'], '초기 조건이 값의 마스크 처리나 배열 쓰기보다 앞에 있습니다. 따라서 이 경로는 아무 비트도 지우거나 설정하지 않습니다.')]), 'os1372': ('빈 좌석을 안내받는 것과 예약하는 것은 다릅니다. 이 함수는 조건에 맞는 빈자리의 번호만 찾아 줍니다.', '빈 구간 검색의 정렬 조건과 예약 단계의 차이를 이해합니다.', '길이 16인 빈 좌석표에서 start=3, nr=3, align_mask=3으로 찾으세요. 시작은 4의 배수여야 하므로 4를 고르고 4,5,6번이 비었는지 확인합니다. 검색 뒤에도 값은 모두 0입니다.', ['bitmap_find_next_zero_area는 연속된 0을 찾습니다. size는 검색 범위의 끝, start는 찾기 시작할 번호, nr은 필요한 칸 수입니다. 여기서는 nr이 양수인 정상 요청을 생각합시다. 0은 아직 사용하지 않는 자리로 볼 수 있습니다.', 'align_mask는 시작 번호를 어떤 간격에 맞출지 알려 줍니다. 간격이 4라면 마스크는 4-1=3입니다. 간격은 1,2,4,8처럼 2의 거듭제곱이고 마스크는 그보다 1 작아야 합니다. 마스크 0은 간격 1이므로 추가 제한이 없습니다.', '이 짧은 함수는 실제 일을 bitmap_find_next_zero_area_off에 맡깁니다. 마지막 인자인 align_offset을 0으로 고정합니다. offset은 정렬 기준을 비켜 놓는 값인데, 기본 함수는 그런 이동 없이 번호 자체를 간격에 맞춥니다.', '본체는 다음 빈칸을 찾고 정렬에 맞게 후보 시작 번호를 올립니다. 요청 구간 안에 1이 있으면 그 1의 다음부터 다시 찾습니다. 예를 들어 빈 16칸에서 start=3, nr=3, 마스크 3이면 시작 4를 골라 4,5,6번을 확인합니다.', '후보의 끝이 size보다 크면 이 원문은 그 끝 번호를 반환합니다. 이는 유효한 시작 번호가 아닙니다. 예를 들어 size=8, start=7, nr=2이면 끝 9를 돌려줄 수 있습니다. 실패가 꼭 size와 같거나 음수라고 생각하면 안 됩니다. 실제 범위와 반환값을 대조해야 합니다.', '성공해도 map의 0을 1로 바꾸지 않습니다. 예약이 필요하면 검색 결과를 확인한 뒤 별도로 표시해야 합니다. 여러 실행 흐름이 같은 표를 쓰면 검색과 예약 사이도 보호해야 합니다. 계산의 넘침, 마스크 조건, 실제 저장 공간은 호출자가 확인해야 합니다.'], [('기본 함수가 실제 검색 함수에 넘기는 align_offset은 얼마일까요?', ['언제나 size와 같아요', '0이에요'], '함수의 마지막 인자가 0으로 적혀 있습니다. 따라서 별도로 정렬 기준을 이동하지 않습니다. size는 검색 범위의 끝이므로 다른 역할입니다.'), ('빈 구간을 찾았다는 반환값을 받으면 예약도 끝난 것일까요?', ['아니요. 검색 뒤에 별도 예약 표시가 필요해요', '네. 해당 비트들이 이미 전부 1로 바뀌었어요'], '본체에는 찾기와 정렬 계산은 있지만 비트를 설정하는 동작은 없습니다. 두 사람이 같은 빈 구간을 볼 수 있으므로 공유할 때는 검색과 예약을 함께 보호하는 규칙이 필요합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_338.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
